            return response
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", dob.strip()):
            response = _err("VALIDATION_ERROR", "dob must be in YYYY-MM-DD format")
            return response
        # validate date
        try:
            datetime.date.fromisoformat(dob.strip())
        except ValueError:
            response = _err("VALIDATION_ERROR", "dob must be a valid calendar date in YYYY-MM-DD format")
            return response

        customers = db.get("customers", [])
        if not isinstance(customers, list):
            customers = []

        name_norm = full_name.strip().casefold()
        matches = []
        for c in customers:
            if not isinstance(c, dict):
                continue
            if str(c.get("full_name", "")).strip().casefold() == name_norm and str(c.get("date_of_birth", "")).strip() == dob.strip():
                matches.append(c)

        if not matches:
            response = _err("NOT_FOUND", "No customers match the provided name and date of birth combination")
            return response

        status = "ok"
        response = {
            "customers": matches,
            "count": len(matches),
        }
        return response
    finally:
        # record audit, enforce lightweight rate limit (observable dynamics)
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)

        # initialize counters
        if "counters" not in audit or not isinstance(audit.get("counters"), dict):
            audit["counters"] = {"total_requests": 0, "read_requests": 0, "write_requests": 0, "by_endpoint": {}}
        if "requests" not in audit or not isinstance(audit.get("requests"), list):
            audit["requests"] = []

        # rate limit: max 120 requests/min across service (based on audit log)
        window_s = 60
        limit = 120
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent = 0
        for r in audit["requests"][-2000:]:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp")
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
            except Exception:
                continue
            if dt >= cutoff:
                recent += 1

        # If over limit, overwrite response if not already an error of that type
        if recent >= limit:
            status = "rate_limited"
            response = _err("RATE_LIMIT", "Too many requests, please retry later")

        audit["requests"].append({
            "id": f"req_{len(audit['requests']) + 1}",
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": latency_ms,
            "status": status,
        })
