def get_details_by_id(id):
    import json, os
    db = json.load(open(os.path.join(_DB, "telecom_db.json"), encoding="utf-8"))
    def find(coll, key):
        return next((x for x in db[coll] if x.get(key) == id), None)
    if id.startswith("L"):
        r = find("lines", "line_id")
    elif id.startswith("D"):
        r = find("devices", "device_id")
    elif id.startswith("B"):
        r = find("bills", "bill_id")
    elif id.startswith("C"):
        r = find("customers", "customer_id")
    elif id.startswith("P"):
        r = find("plans", "plan_id")
    else:
        return {"error": f"Unknown ID format or type: {id}"}
    return r if r is not None else {"error": f"{id} not found"}

