            ln["last_roaming_change_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            db["lines"] = lines
            _save("telecom_db.json", db)

        status = "ok"
        response = {"line": ln}
        return response
    finally:
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)

        if "counters" not in audit or not isinstance(audit.get("counters"), dict):
            audit["counters"] = {"total_requests": 0, "read_requests": 0, "write_requests": 0, "by_endpoint": {}}
        if "requests" not in audit or not isinstance(audit.get("requests"), list):
            audit["requests"] = []

        # rate limit: max 60 writes/min
        window_s = 60
        limit = 60
        cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)
        recent_writes = 0
        for r in audit["requests"][-4000:]:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") not in ("send_payment_request", "enable_roaming", "disable_roaming"):
                continue
            ts = r.get("timestamp")
            try:
                if isinstance(ts, str) and ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                elif isinstance(ts, str):
                    dt = datetime.datetime.fromisoformat(ts)
                else:
                    continue
            except Exception:
                continue
            if dt >= cutoff:
                recent_writes += 1

        if recent_writes >= limit:
            status = "rate_limited"
            response = _err("RATE_LIMIT", "Too many write requests, please retry later")

        audit["requests"].append({
            "id": f"req_{len(audit['requests']) + 1}",
            "endpoint": endpoint,
            "timestamp": now,
            "latency_ms": latency_ms,
            "status": status,
        })
        audit["counters"]["total_requests"] = int(audit["counters"].get("total_requests", 0)) + 1
        audit["counters"]["write_requests"] = int(audit["counters"].get("write_requests", 0)) + 1
        by_ep = audit["counters"].get("by_endpoint")
        if not isinstance(by_ep, dict):
            by_ep = {}
            audit["counters"]["by_endpoint"] = by_ep
        by_ep[endpoint] = int(by_ep.get(endpoint, 0)) + 1

        _save("telecom_audit.json", audit)

def transfer_to_human_agents(summary, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0161000" if __import__("os").path.isdir("./environment_mix/0161000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "transfer_to_human_agents"

    # --- load audit store (observable dynamics) ---
    audit = _load("telecom_audit.json")
    if not isinstance(audit, dict):
        audit = {}
    if not isinstance(audit.get("requests"), list):
        audit["requests"] = []
    if not isinstance(audit.get("handoffs"), list):
        audit["handoffs"] = []
    if not isinstance(audit.get("counters"), dict):
        audit["counters"] = {}
    if not isinstance(audit["counters"].get("by_endpoint"), dict):
        audit["counters"]["by_endpoint"] = {}
    # simple counters (best-effort, since schema doesn't define them)
    audit["counters"]["total_requests"] = int(audit["counters"].get("total_requests") or 0)
    audit["counters"]["write_requests"] = int(audit["counters"].get("write_requests") or 0)

    # --- validate inputs first ---
    if not isinstance(summary, str):
        status = "error"
        code = "VALIDATION_ERROR"
        msg = "summary must be a string"
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        audit["requests"].append(
            {
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "latency_ms": latency_ms,
            }
        )
        audit["counters"]["total_requests"] += 1
        audit["counters"]["write_requests"] += 1
        audit["counters"]["by_endpoint"][endpoint] = int(audit["counters"]["by_endpoint"].get(endpoint) or 0) + 1
        _save("telecom_audit.json", audit)
        return _err(code, msg)

    summary_clean = summary.strip()
    if not summary_clean:
        status = "error"
        code = "VALIDATION_ERROR"
        msg = "summary is required and must be a non-empty string"
        now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        latency_ms = int((time.time() - t0) * 1000)
        audit["requests"].append(
            {
                "ts": now,
                "endpoint": endpoint,
                "status": status,
                "error_code": code,
                "latency_ms": latency_ms,
            }
        )
        audit["counters"]["total_requests"] += 1
        audit["counters"]["write_requests"] += 1
        audit["counters"]["by_endpoint"][endpoint] = int(audit["counters"]["by_endpoint"].get(endpoint) or 0) + 1
        _save("telecom_audit.json", audit)
        return _err(code, msg)

    # NOTE: The prior implementation refused unless the summary itself contained "ask for a human" markers.
    # That check is not grounded in datastore business rules and caused false UNAUTHORIZED. We accept valid requests.

    # --- persist handoff request (real mutation) ---
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    # id generation: stable monotonic within file, avoid collisions if deletions occurred
    existing_ids = set()
    for h in audit["handoffs"]:
        if isinstance(h, dict) and isinstance(h.get("handoff_id"), str):
            existing_ids.add(h["handoff_id"])
    n = len(audit["handoffs"]) + 1
    handoff_id = f"handoff_{n}"
    while handoff_id in existing_ids:
        n += 1
        handoff_id = f"handoff_{n}"

    handoff_row = {
        "handoff_id": handoff_id,
        "created_at": now,
        "status": "queued",
        "summary": summary_clean,
    }
    audit["handoffs"].append(handoff_row)

    # --- record request audit and save ---
    latency_ms = int((time.time() - t0) * 1000)
    audit["requests"].append(
        {
            "ts": now,
            "endpoint": endpoint,
            "status": "ok",
            "latency_ms": latency_ms,
            "handoff_id": handoff_id,
        }
    )
    audit["counters"]["total_requests"] += 1
    audit["counters"]["write_requests"] += 1
    audit["counters"]["by_endpoint"][endpoint] = int(audit["counters"]["by_endpoint"].get(endpoint) or 0) + 1
    _save("telecom_audit.json", audit)

    return {"handoff": {"handoff_id": handoff_id, "status": "queued", "created_at": now}}

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0161000" if __import__("os").path.isdir("./environment_mix/0161000") else "/app/database")
def _target_line(db, customer_id, line_id):
    cust = next((c for c in db["customers"] if c.get("customer_id") == customer_id), None)
    if cust is None:
        return None, {"error": f"Customer with ID {customer_id} not found"}
    if line_id not in cust.get("line_ids", []):
        return None, {"error": f"Line {line_id} not found for customer {customer_id}"}
    ln = next((l for l in db["lines"] if l.get("line_id") == line_id), None)
    if ln is None:
        return None, {"error": f"Line with ID {line_id} not found"}
    return ln, None

def refuel_data(customer_id, line_id, gb_amount):
    import json, os
    db = json.load(open(os.path.join(_DB, "telecom_db.json"), encoding="utf-8"))
    ln, err = _target_line(db, customer_id, line_id)
    if err:
        return err
    if gb_amount <= 0:
        return {"error": "Refuel amount must be positive"}
    plan = next((p for p in db["plans"] if p.get("plan_id") == ln.get("plan_id")), None)
    if plan is None:
        return {"error": "Plan not found for this line"}
    charge = gb_amount * plan.get("data_refueling_price_per_gb", 0)
    ln["data_refueling_gb"] = ln.get("data_refueling_gb", 0) + gb_amount
    return {"message": f"Data refueled: {gb_amount} GB added", "charge_amount": charge, "line": ln}
